from PIL import Image
img = Image.open('/app/output/final_poster.png')

# Check for each accent color presence
color_ranges = {
    'Blue (JS, headers)': ((110,135), (150,175), (235,255)),
    'Amber (Python)': ((210,240), (165,190), (95,120)),
    'Mint (TypeScript)': ((145,170), (195,225), (95,125)),
    'Coral (AI, Rust)': ((235,255), (110,140), (130,160)),
}

found = {k: False for k in color_ranges}
# Sample every 10th pixel
for y in range(0, 4961, 10):
    for x in range(0, 3508, 10):
        r, g, b = img.getpixel((x, y))
        for name, (rr, gr, br) in color_ranges.items():
            if rr[0] <= r <= rr[1] and gr[0] <= g <= gr[1] and br[0] <= b <= br[1]:
                found[name] = True

print('Accent color presence in poster:')
for name, present in found.items():
    print(f'  {name}: {\"FOUND\" if present else \"MISSING\"} ')

# Check text presence - look for white-ish pixels in header region
white_count = 0
for y in range(150, 500):
    for x in range(150, 3350, 5):
        r, g, b = img.getpixel((x, y))
        if r > 180 and g > 190 and b > 230:
            white_count += 1
print(f'\\nWhite-ish pixels in header: {white_count} (text presence: {\"YES\" if white_count > 10 else \"NO\"})')
"

